{
    var blogSummariesQuery =
        from blog in blogContext.Blogs
        select new BlogSummary(
            blog.Id,
            blog.Title,
            blog.Posts.Select(post => new PostSummary(post.Id, post.Title)),
            blog.Contributors.Select(contributor => new ContributorSummary(contributor.Id, contributor.Name)));

    var blogSummaries = await blogSummariesQuery.ToListAsync(cancellationToken);
    return blogSummaries;
}
